parameters.functionCode:
const contacts = $input.all();
const results = [];

for (const item of contacts) {
  const contact = item.json;
  let newScore = contact.lead_score || 0;
  let newStatus = contact.lead_status;
  let isHotLead = false;

  // Decay score jika tidak ada aktivitas > 7 hari
  const lastActivity = new Date(contact.last_activity);
  const daysSinceActivity = (Date.now() - lastActivity.getTime()) / (1000 * 60 * 60 * 24);

  if (daysSinceActivity > 7) {
    newScore = Math.max(0, newScore - 5);
  }
  if (daysSinceActivity > 30) {
    newScore = Math.max(0, newScore - 15);
  }

  // Update status berdasarkan score
  if (newScore >= 80) {
    newStatus = 'qualified';
    isHotLead = true;
  } else if (newScore >= 50) {
    newStatus = 'contacted';
  } else if (newScore >= 20) {
    newStatus = 'new';
  }

  // Bonus score berdasarkan engagement frequency
  if (contact.activity_count > 10) newScore += 10;
  else if (contact.activity_count > 5) newScore += 5;

  results.push({
    json: {
      ...contact,
      new_score: newScore,
      new_status: newStatus,
      is_hot_lead: isHotLead,
      score_changed: newScore !== contact.lead_score,
      status_changed: newStatus !== contact.lead_status
    }
  });
}

return results;

